/**  Answer to a conflict. */
export type ConflictChoice = 
/**  Replace. */
"Overwrite" | 
/**  Skip this file. */
"Skip" | 
/**  Keep both. */
"Rename" | 
/**  Append from destination size. */
"Resume";

/**  Pending conflict decision id. */
export type ConflictId = string;

/**  Both sides of a conflict (`TransferEvent::Conflict`, `ApiError::Conflict`). */
export type ConflictInfo = {
	/**  Destination path. */
	path: string,
	/**  Source size. */
	src_size: number,
	/**  Source mtime, unix millis. */
	src_mtime: number | null,
	/**  Destination size. */
	dst_size: number,
	/**  Destination mtime, unix millis. */
	dst_mtime: number | null,
};

/**  What to do when the destination exists. */
export type ConflictPolicy = 
/**  Emit `TransferEvent::Conflict` and wait for `conflict_reply`. */
"Ask" | 
/**  Replace. */
"Overwrite" | 
/**  Keep destination, skip file. */
"Skip" | 
/**  Write as `name (1).ext`, `name (2).ext`, … */
"Rename" | 
/**  Append if destination is smaller, otherwise ask. */
"ResumeIfSmaller";

/**  Progress step. IPC: `SessionEvent::Connecting.step`. */
export type ConnectStep = 
/**  DNS lookup. */
"Resolving" | 
/**  TCP connect (or direct-tcpip through the previous hop). */
"Connecting" | 
/**  KEX + host key check. */
"Handshake" | 
/**  User auth. */
"Authenticating" | 
/**  Opening PTY / shell / subsystem. */
"OpeningChannel";

/**  A directory listing. `path` is absolute and normalized (remote: POSIX). */
